   592→static C_KZG_RET compute_commitment_to_aggregated_interpolation_poly(
   593→    g1_t *commitment_out,
   594→    const fr_t *r_powers,
   595→    const uint64_t *cell_indices,
   596→    const Cell *cells,
   597→    uint64_t num_cells,
   598→    const KZGSettings *s
   599→) {
   600→    C_KZG_RET ret;
   601→    bool *is_cell_used = NULL;
   602→    fr_t *aggregated_column_cells = NULL;
   603→    fr_t *column_interpolation_poly = NULL;
   604→    fr_t *aggregated_interpolation_poly = NULL;
   605→
   606→    ////////////////////////////////////////////////////////////////////////////////////////////////
   607→    // Array allocations
   608→    ////////////////////////////////////////////////////////////////////////////////////////////////
   609→
   610→    ret = new_bool_array(&is_cell_used, CELLS_PER_EXT_BLOB);
   611→    if (ret != C_KZG_OK) goto out;
   612→    ret = new_fr_array(&aggregated_column_cells, FIELD_ELEMENTS_PER_EXT_BLOB);
   613→    if (ret != C_KZG_OK) goto out;
   614→    ret = new_fr_array(&column_interpolation_poly, FIELD_ELEMENTS_PER_CELL);
   615→    if (ret != C_KZG_OK) goto out;
   616→    ret = new_fr_array(&aggregated_interpolation_poly, FIELD_ELEMENTS_PER_CELL);
   617→    if (ret != C_KZG_OK) goto out;
   618→
   619→    ////////////////////////////////////////////////////////////////////////////////////////////////
   620→    // Aggregate cells from the same column
   621→    ////////////////////////////////////////////////////////////////////////////////////////////////
   622→
   623→    /* Start with zeroed out columns */
   624→    for (size_t i = 0; i < CELLS_PER_EXT_BLOB; i++) {
   625→        for (size_t j = 0; j < FIELD_ELEMENTS_PER_CELL; j++) {
   626→            size_t index = i * FIELD_ELEMENTS_PER_CELL + j;
   627→            aggregated_column_cells[index] = FR_ZERO;
   628→        }
   629→    }
   630→
   631→    /*
   632→     * Vertically collapse cells of the 2D matrix into a single array: `aggregated_column_cells`.
   633→     *
   634→     * For each provided cell, go over its field elements, and scale them by the appropriate power
   635→     * of r. Then aggregate all field elements on the same vertical slice into a single array.
   636→     */
   637→    for (uint64_t cell_index = 0; cell_index < num_cells; cell_index++) {
   638→        /* Determine which column this cell belongs to */
   639→        uint64_t column_index = cell_indices[cell_index];
   640→
   641→        /* Iterate over every field element of this cell: scale it and aggregate it */
   642→        for (size_t fr_index = 0; fr_index < FIELD_ELEMENTS_PER_CELL; fr_index++) {
   643→            fr_t original_fr, scaled_fr;
   644→
   645→            /* Get the field element at this offset */
   646→            size_t offset = fr_index * BYTES_PER_FIELD_ELEMENT;
   647→            ret = bytes_to_bls_field(
   648→                &original_fr, (const Bytes32 *)&cells[cell_index].bytes[offset]
   649→            );
   650→            if (ret != C_KZG_OK) goto out;
